INSERT INTO categories (id, name, description, icon, sort_order) VALUES ('ai-assistant', 'AI Assistant & Chat', 'The world''s most powerful AI assistants. Write, code, research, create images, and automate tasks. From ChatGPT and Claude to Gemini and Perplexity — find your perfect AI partner.', 'MessageSquare', 0);
INSERT INTO categories (id, name, description, icon, sort_order) VALUES ('ai-image', 'AI Image & Design', 'Create stunning visuals with AI. Generate images from text, edit photos, and design graphics. Midjourney for artistic quality, Ideogram for perfect text rendering, Leonardo AI for 3D and motion.', 'Image', 1);
INSERT INTO categories (id, name, description, icon, sort_order) VALUES ('ai-video', 'AI Video', 'Generate and edit videos with AI. Text-to-video, image-to-video, 4K upscaling, and AI avatar creation. Runway Gen-4 and HeyGen are the leading platforms for video and avatar creation.', 'Video', 2);
INSERT INTO categories (id, name, description, icon, sort_order) VALUES ('ai-voice-music', 'AI Voice & Music', 'Clone voices, generate speech, and create music with AI. ElevenLabs for human-quality voiceovers. Suno for complete AI-generated songs in any genre. Udio for fast music creation.', 'Music', 3);
INSERT INTO categories (id, name, description, icon, sort_order) VALUES ('ai-code', 'AI Code & Dev Tools', 'Code faster with AI pair programming. GitHub Copilot integrates into your IDE. Cursor is the AI-native editor used by teams at OpenAI, Stripe, and Figma. v0.dev builds UIs from prompts.', 'Code2', 4);
INSERT INTO categories (id, name, description, icon, sort_order) VALUES ('ai-workspace', 'AI Workspace', 'AI-powered productivity and collaboration. Notion Business with AI included. Manus AI for autonomous agents. Otter.ai for meeting transcription. Gamma for AI presentations.', 'Layout', 5);
INSERT INTO categories (id, name, description, icon, sort_order) VALUES ('ai-writing', 'AI Writing & SEO', 'AI-powered content writing and SEO tools. Writesonic Individual for blog writing, SEO content, marketing copy, and social media posts. Outrank competitors with AI-optimized content.', 'PenTool', 6);
INSERT INTO categories (id, name, description, icon, sort_order) VALUES ('bundles', 'Bundles & Packages', 'Save more with curated AI tool bundles. Designed for students, freelancers, and businesses. Multiple premium tools at a discounted package price. Includes setup and onboarding.', 'Package', 7);
